const input=$json.body??$json;
const perf=input.portfolio_performance??{};
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const sample=Math.max(0,Number(perf.historical_sample_size??input.historical_sample_size??0));
const netDelta=Number(perf.net_profit_delta??input.net_profit_delta);
const marginDelta=Number(perf.margin_delta??input.margin_delta);
const valid=Number.isFinite(netDelta)||Number.isFinite(marginDelta);
let confidence=sample>=20?"high":sample>=10?"medium":"low";
let factor=1;
let rationale="insufficient evidence for calibration";
if(valid){
  if(confidence==="high"){
    if((Number.isFinite(marginDelta)&&marginDelta<-0.10)||(Number.isFinite(netDelta)&&netDelta<0)){factor=0.95;rationale="high-confidence underperformance";}
    else if((Number.isFinite(marginDelta)&&marginDelta>0.10)&&(Number.isFinite(netDelta)&&netDelta>0)){factor=1.03;rationale="high-confidence outperformance";}
    else rationale="high-confidence performance within calibration band";
  } else if(confidence==="medium"){
    if(Number.isFinite(marginDelta)&&marginDelta<-0.15){factor=0.97;rationale="medium-confidence underperformance";}
    else if(Number.isFinite(marginDelta)&&marginDelta>0.15&&Number.isFinite(netDelta)&&netDelta>0){factor=1.02;rationale="medium-confidence outperformance";}
    else rationale="medium-confidence performance within calibration band";
  }
}
const baseMao=Number(input.base_mao??input.dynamic_mao??input.mao);
const adjustedMao=Number.isFinite(baseMao)?baseMao*factor:null;
let status="calibration_ready",nextWorkflow="WF-287",humanReview=false;
if(blockers.length){status="calibration_blocked";nextWorkflow="WF-126";humanReview=true;}
else if(!valid){status="performance_evidence_invalid";nextWorkflow="WF-285";humanReview=true;}
else if(confidence==="low"){status="low_confidence_human_review";nextWorkflow="WF-126";humanReview=true;}
else if(!Number.isFinite(baseMao)){status="base_mao_missing";nextWorkflow="WF-126";humanReview=true;}
const calibration={sample_size:sample,confidence,base_mao:Number.isFinite(baseMao)?baseMao:null,adjustment_factor:factor,adjusted_mao:adjustedMao,net_profit_delta:Number.isFinite(netDelta)?netDelta:null,margin_delta:Number.isFinite(marginDelta)?marginDelta:null,rationale,rule_note:"70% rule is secondary/reference only; calibration remains asset-specific and economics-driven."};
return [{json:{...input,workflow:"WF-286",workflow_name:"Portfolio Performance → Underwriting Calibration & Dynamic MAO Strategy Feedback Controller",status,calibration,next_workflow:nextWorkflow,human_review_required:humanReview,audit:{event_type:"underwriting_calibration_dynamic_mao",idempotency_key:input.idempotency_key||`wf-286:${input.deal_id||"unknown"}:${input.close_id||"none"}:${input.version||1}`}}}];
